const durations=[800,120,160,120,400];
function frameAt(d, t){const total=d.reduce((a,b)=>a+b,0);let at=Math.max(t,0)%total;for(let i=0;i<d.length;i++){if(at<d[i])return i;at-=d[i];}return d.length-1;}
const times=[0,799,800,919,920,1079,1080,1199,1200,1599,1600];
const uni=[100,100,100,100,100];
const out={authored:{durations_ms:durations,total_ms:durations.reduce((a,b)=>a+b,0),frames:Object.fromEntries(times.map(t=>[t,frameAt(durations,t)]))},uniform:{durations_ms:uni,total_ms:500,frames:Object.fromEntries(times.map(t=>[t,frameAt(uni,t)])), boundaries:[0,100,200,300,400,500]}};
console.log(JSON.stringify(out,null,1));
EOF
