import zlib,struct,glob,os
def load(p):
    d=open(p,'rb').read(); assert d[:8]==b'\x89PNG\r\n\x1a\n'
    i=8; idat=b''; w=h=0; ct=0; bd=0; plte=None; trns=None
    while i<len(d):
        L=struct.unpack('>I',d[i:i+4])[0]; t=d[i+4:i+8]; body=d[i+8:i+8+L]; i+=12+L
        if t==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',body[:10])
        elif t==b'IDAT': idat+=body
        elif t==b'PLTE': plte=body
        elif t==b'tRNS': trns=body
    raw=zlib.decompress(idat)
    ch={0:1,2:3,3:1,4:2,6:4}[ct]; bpp=max(1,ch*bd//8); stride=w*ch*bd//8
    rows=[]; prev=bytearray(stride); pos=0
    for y in range(h):
        f=raw[pos]; pos+=1; line=bytearray(raw[pos:pos+stride]); pos+=stride
        for x in range(stride):
            a=line[x-bpp] if x>=bpp else 0; b=prev[x]; c=prev[x-bpp] if x>=bpp else 0
            if f==1: line[x]=(line[x]+a)&255
            elif f==2: line[x]=(line[x]+b)&255
            elif f==3: line[x]=(line[x]+((a+b)>>1))&255
            elif f==4:
                pa=abs(b-c);pb=abs(a-c);pc=abs(a+b-2*c)
                pr=a if pa<=pb and pa<=pc else (b if pb<=pc else c)
                line[x]=(line[x]+pr)&255
        rows.append(bytes(line)); prev=line
    px=[]
    for y in range(h):
        r=[]
        for x in range(w):
            if ct==6: r.append(tuple(rows[y][x*4:x*4+4]))
            elif ct==2: r.append(tuple(rows[y][x*3:x*3+3])+(255,))
            elif ct==3:
                idx=rows[y][x]; a=trns[idx] if trns and idx<len(trns) else 255
                r.append(tuple(plte[idx*3:idx*3+3])+(a,))
            else: raise SystemExit("unsupported ct %d"%ct)
        px.append(r)
    return w,h,px
def summarize(p):
    w,h,px=load(p)
    op=[(x,y) for y in range(h) for x in range(w) if px[y][x][3]>0]
    xs=[x for x,_ in op]; ys=[y for _,y in op]
    bottom=max(ys); bottom_cols=sorted(x for x,y in op if y==bottom)
    cols={}
