    cyan=[(x,y) for y in range(h) for x in range(w) if px[y][x][3]>0 and px[y][x][2]>px[y][x][0]+60]
    cy=[y for _,y in cyan]; cx=[x for x,_ in cyan]
    semi=sum(1 for y in range(h) for x in range(w) if 0<px[y][x][3]<255)
    print(os.path.basename(os.path.dirname(p))+"/"+os.path.basename(p), f"{w}x{h}", "bbox x[%d..%d] y[%d..%d]"%(min(xs),max(xs),min(ys),max(ys)), "bottom_row",bottom,"bottom_cols[%d..%d] n=%d"%(bottom_cols[0],bottom_cols[-1],len(bottom_cols)), "opaque",len(op),"semi",semi, "cyan n=%d x[%s..%s] y[%s..%s]"%(len(cyan),min(cx) if cx else '-',max(cx) if cx else '-',min(cy) if cy else '-',max(cy) if cy else '-'), "colors",{k:v for k,v in cols.items()})
for d in ("assets/robot-idle","work/cf09-production-01/returned","work/cf09-production-01/corrected"):
    for p in sorted(glob.glob(d+"/*.png")): summarize(p)
